/**
 * Builds the OpenAPI 3.1 document FROM the Zod schemas.
 *
 * The direction matters: the schemas are the contract and the document is
 * derived, so the two cannot drift. A hand-written spec is a second source of
 * truth that is wrong the first time somebody adds a field.
 *
 * `docs/api/openapi.json` is generated by `npm run api:spec` and committed, so a
 * pull request that changes the contract shows it as a diff.
 */

import { OpenApiGeneratorV31 } from '@asteasolutions/zod-to-openapi'
import type { OpenAPIObject } from 'openapi3-ts/oas31'

import { registry } from '@/api/registry'
import '@/api/contracts'

export function buildOpenApiDocument(): OpenAPIObject {
  return new OpenApiGeneratorV31(registry.definitions).generateDocument({
    openapi: '3.1.0',
    info: {
      title: 'Bigorna API',
      version: '1.0.0',
      description: [
        'API do Bigorna — controle financeiro PF + PJ.',
        '',
        'Convenções (ver `src/api/README.md`):',
        '- Dinheiro é sempre INTEIRO de centavos. Datas são `YYYY-MM-DD`, meses `YYYY-MM`.',
        '- Erros seguem RFC 9457 (`application/problem+json`), com `code` legível por máquina.',
        '- Coleção responde `{ data, meta: { total } }`; recurso único responde o objeto.',
        '- Todo endpoint exige sessão e é escopado por `userId` (ADR-0008).',
      ].join('\n'),
    },
    // The paths already carry `/api/v1`, so the server is the app's own origin.
    servers: [{ url: '/', description: 'Mesma origem do app' }],
    /**
     * There is no security scheme yet, and saying so is part of the decision:
     * ADR-0008 §1 records that this phase has no authentication and that the
     * mitigation is operational (a private environment). Declaring a scheme the
     * server does not enforce would document a protection that does not exist.
     */
  })
}
